begin; create extension if not exists pgtap with schema extensions; set local search_path=public,extensions; select extensions.plan(5);
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at) values('00000000-0000-0000-0000-000000001201','authenticated','authenticated','integrity-summary@example.com','',now(),now(),now());
set local role postgres; insert into accounts(id,user_id,name) values(9921,'00000000-0000-0000-0000-000000001201','One'),(9922,'00000000-0000-0000-0000-000000001201','Two');
insert into instruments(id,user_id,ticker,display_name,currency,instrument_type) values(9921,'00000000-0000-0000-0000-000000001201','I1','One','KRW','market'),(9922,'00000000-0000-0000-0000-000000001201','I2','Two','KRW','market');
insert into holdings(user_id,account_id,ticker,quantity,avg_price) values('00000000-0000-0000-0000-000000001201',9921,'I1',1,10),('00000000-0000-0000-0000-000000001201',9922,'I2',2,20);
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000001201',true); set local role authenticated;
select extensions.is((public.app_get_portfolio_integrity()->>'never_verified_count')::integer,2,'starts with two never-verified holdings');
select extensions.lives_ok($$select public.app_verify_holding((select id from holdings where ticker='I1'),1,array['quantity'],current_date,null,'11111111-1111-4111-8111-111111111111','app')$$,'verifies one holding');
select extensions.is((public.app_get_portfolio_integrity()->>'verified_count')::integer,1,'summary counts one verified holding');
select * from public.app_save_holding((select id from holdings where ticker='I1'),9921,'I1',2,10,'user','changed after verification');
select extensions.is((public.app_get_portfolio_integrity()->>'changed_count')::integer,1,'summary reports changed since verification');
select extensions.is(jsonb_array_length(public.app_get_portfolio_integrity()->'accounts'),2,'summary groups by account');
select * from extensions.finish(); rollback;
